#pragma once
#include <cstring>
#include <iostream>
#include <iomanip>
#include <vector>
#include <string>

class RegisterFile {
public:
    static constexpr int REG_NUM = 32;
    using Immediate = unsigned long;

private:
    Immediate prev[REG_NUM];
    Immediate next[REG_NUM];

public:
    RegisterFile() {
        std::memset(prev, 0, sizeof(prev));
        std::memset(next, 0, sizeof(next));
    }

    void tick() {
        std::memcpy(prev, next, sizeof(prev));
    }

    Immediate read(int id) {
        if (id == 0) return 0;
        return prev[id];
    }

    void write(int id, Immediate val) {
        next[id] = val;
    }

    void debug() {
        const std::vector<std::string> reg_names = {
            "zero", "ra",  "sp",  "gp",  "tp",  "t0",  "t1",  "t2",
            "s0",  "s1",  "a0",  "a1",  "a2",  "a3",  "a4",  "a5",
            "a6",  "a7",  "s2",  "s3",  "s4",  "s5",  "s6",  "s7",
            "s8",  "s9",  "s10", "s11", "t3",  "t4",  "t5",  "t6"
        };

        std::cout << "Register State:\n";
        for (int i = 0; i < REG_NUM; i += 8) {
            for (int j = 0; j < 8; ++j) {
                int idx = i + j;
                std::cout << std::setw(6) << reg_names[idx] << ": ";
                debug_immediate(prev[idx]);
                if (j < 7) std::cout << " | ";
            }
            std::cout << "\n";
        }
    }

private:
    static void debug_immediate(Immediate val) {
        std::cout << "0x" << std::hex << std::setw(16) << std::setfill('0') << val;
    }
};
